import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import RequestUpdate from "../layouts/Requestupdates";
import SuggestionModal from "../layouts/SuggestionModal";
import InternReferralForm from "../layouts/Intern";
import FeedbackForm from "./FeedbackForm";
import EvaluateModal from "../components/EvaluateModal";

import {
  RefreshCcw, Lightbulb, Briefcase, MessageSquare, ClipboardCheck, PlusCircle, Bot, Calendar
} from "lucide-react";

const RightSidebar = () => {
  const navigate = useNavigate();
  const [isRequestUpdateOpen, setIsRequestUpdateOpen] = useState(false);
  const [isSuggestionModalOpen, setIsSuggestionModalOpen] = useState(false);
  const [isInternModalOpen, setIsInternModalOpen] = useState(false);
  const [isFeedbackFormOpen, setIsFeedbackFormOpen] = useState(false);
  const [isEvaluateModalOpen, setISEvaluateModalOpen] = useState(false);

  // Student specific modals
  const [studentProvideUpdateOpen, setStudentProvideUpdateOpen] = useState(false);
  const [studentMeetingUpdateOpen, setStudentMeetingUpdateOpen] = useState(false);
  const [studentFeedbackOpen, setStudentFeedbackOpen] = useState(false);
  const [studentTestimonialsOpen, setStudentTestimonialsOpen] = useState(false);

  const handleNavigation = (path) => {
    if (path === "/request-update") {
      setIsRequestUpdateOpen(true);
    } else if (path === "/share-suggestion") {
      setIsSuggestionModalOpen(true);
    } else if (path === "/internship-referral") {
      setIsInternModalOpen(true);
    } else if (path === "/evaluate") {
      setISEvaluateModalOpen(true);
    } else {
      try {
        console.log("Navigating to:", path);
        navigate(path);
      } catch (error) {
        console.error("Navigation error:", error);
      }
    }
  };

  return (
    <aside className="w-[clamp(12rem,18vw,16rem)] bg-gradient-to-t from-purple-300 via-indigo-50 to-blue-100 dark:from-slate-800 dark:via-slate-900 dark:to-black shadow-lg px-[clamp(0.75rem,1.5vw,1.25rem)] py-[clamp(1rem,2vh,1.5rem)] flex flex-col justify-between overflow-y-auto [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
      <div>
        {(() => {
          const role = (localStorage.getItem('user_role') || '').toLowerCase();
          const isStudent = role === 'student';
          if (isStudent) {
            return (
              <>
                <h2 className="text-[clamp(1.25rem,2vw,1.5rem)] font-bold mb-[1vh] text-blue-900 dark:text-white">Actions</h2>
                <ActivityButton
                  icon={<RefreshCcw className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-blue-600" />}
                  label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Provide Update</span>}
                  onClick={() => setStudentProvideUpdateOpen(true)}
                />
                <ActivityButton
                  icon={<Calendar className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-purple-600" />}
                  label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Meeting Update</span>}
                  onClick={() => setStudentMeetingUpdateOpen(true)}
                />
                <ActivityButton
                  icon={<MessageSquare className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-indigo-600" />}
                  label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Submit Feedback</span>}
                  onClick={() => setStudentFeedbackOpen(true)}
                />
                <ActivityButton
                  icon={<ClipboardCheck className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-green-600" />}
                  label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Testimonials</span>}
                  onClick={() => setStudentTestimonialsOpen(true)}
                />
              </>
            )
          }
          // default (mentor/admin) view
          return (
            <>
              <button
                className="w-full bg-blue-100 hover:bg-blue-200 text-blue-900 font-bold rounded-xl py-[clamp(0.5rem,1vh,0.75rem)] mb-[1vh] flex items-center justify-center gap-[clamp(0.5rem,1vw,0.75rem)] text-[clamp(1rem,1.5vw,1.25rem)] dark:bg-blue-900/50 dark:hover:bg-blue-800/60 dark:text-blue-200"
                onClick={() => handleNavigation("/new-worklet")}
              >
                <PlusCircle className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)]" /> <span className="text-[clamp(1.25rem,2vw,1.5rem)]">New Worklet</span>
              </button>
              <h2 className="text-[clamp(1.25rem,2vw,1.5rem)] font-bold mb-[1vh] text-blue-900 dark:text-white">Activities</h2>
              <ActivityButton
                icon={<RefreshCcw className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-blue-600" />}
                label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Request Update</span>}
                onClick={() => handleNavigation("/request-update")}
              />
              <ActivityButton
                icon={<Lightbulb className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-sky-500" />}
                label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Share Suggestion</span>}
                onClick={() => handleNavigation("/share-suggestion")}
              />
              <ActivityButton
                icon={<Briefcase className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-purple-600" />}
                label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Internship Referral</span>}
                onClick={() => handleNavigation("/internship-referral")}
              />
              <ActivityButton
                icon={<MessageSquare className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-indigo-600" />}
                label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Submit Feedback</span>}
                onClick={() => setIsFeedbackFormOpen(true)}
              />
              <ActivityButton
                icon={<ClipboardCheck className="w-[clamp(1rem,1.5vw,1.25rem)] h-[clamp(1rem,1.5vw,1.25rem)] text-green-600" />}
                label={<span className="text-[clamp(0.875rem,1.2vw,1rem)] font-semibold">Evaluate</span>}
                onClick={() => handleNavigation("/evaluate")}
              />
            </>
          )
        })()}
      </div>
      <div className="text-center">
        <button
          onClick={() => handleNavigation("/ray")}
          className="group relative mx-auto w-[clamp(3rem,4vw,3.5rem)] h-[clamp(3rem,4vw,3.5rem)] rounded-2xl bg-gradient-to-br from-purple-400 to-blue-400 
                             hover:from-purple-500 hover:to-blue-500 flex items-center justify-center 
                             text-[clamp(0.875rem,1.2vw,1rem)] font-bold text-white shadow transition-all duration-200 
                             hover:shadow-lg transform hover:scale-105 cursor-pointer overflow-hidden"
          aria-label="RAY Support Bot"
        >
          <span className="absolute transition-opacity duration-200 opacity-100 group-hover:opacity-0">
            <Bot className="w-[clamp(1.5rem,2vw,2rem)] h-[clamp(1.5rem,2vw,2rem)]" />
          </span>
          <span className="absolute transition-opacity duration-500 opacity-0 group-hover:opacity-100">
            RAY
          </span>
        </button>
        <p className="text-[clamp(0.75rem,1vw,0.875rem)] text-gray-600 mt-[0.25vh] dark:text-slate-400">Support</p>
      </div>

      {/* Modals */}
      {/* Mentor/Admin Modals */}
      <RequestUpdate
        isOpen={isRequestUpdateOpen}
        onClose={() => setIsRequestUpdateOpen(false)}
      />
      <SuggestionModal
        isOpen={isSuggestionModalOpen}
        onClose={() => setIsSuggestionModalOpen(false)}
      />
      <FeedbackForm
        isOpen={isFeedbackFormOpen}
        onClose={() => setIsFeedbackFormOpen(false)}
      />
      {isInternModalOpen && (
        <div className="fixed inset-0 flex items-start justify-center bg-black bg-opacity-40 z-50 p-4 overflow-y-auto">
          <div className="relative w-full max-w-3xl bg-white rounded-xl mt-10 mb-10 dark:bg-slate-900">
            <div className=" top-0 right-0 flex justify-end bg-white rounded-t-xl p-2 dark:bg-slate-900">
              <button
                onClick={() => setIsInternModalOpen(false)}
                className="text-3xl text-purple-700 hover:text-purple-900 font-bold z-10 w-10 h-10 flex items-center justify-center rounded-full hover:bg-purple-100 transition-colors"
              >
                X
              </button>
            </div>
            <div className="p-4">
              <InternReferralForm />
            </div>
          </div>
        </div>
      )}
      <EvaluateModal
        isOpen={isEvaluateModalOpen}
        onClose={() => setISEvaluateModalOpen(false)}
      />

      {/* Student Modals (simple placeholders) */}
      {studentProvideUpdateOpen && (
        <SimpleModal title="Provide Update" onClose={() => setStudentProvideUpdateOpen(false)}>
          <p className="text-sm text-slate-600 dark:text-slate-300 mb-3">Share your latest progress on assigned worklets.</p>
          <textarea className="w-full h-28 border rounded-md px-3 py-2 dark:bg-slate-700 dark:text-white dark:border-slate-600" placeholder="Type your update..." />
          <div className="mt-3 text-right">
            <button onClick={() => setStudentProvideUpdateOpen(false)} className="px-4 py-2 bg-blue-600 text-white rounded-md">Submit</button>
          </div>
        </SimpleModal>
      )}
      {studentMeetingUpdateOpen && (
        <SimpleModal title="Meeting Update" onClose={() => setStudentMeetingUpdateOpen(false)}>
          <p className="text-sm text-slate-600 dark:text-slate-300 mb-3">Add notes or outcomes from your recent meeting.</p>
          <textarea className="w-full h-28 border rounded-md px-3 py-2 dark:bg-slate-700 dark:text-white dark:border-slate-600" placeholder="Meeting notes..." />
          <div className="mt-3 text-right">
            <button onClick={() => setStudentMeetingUpdateOpen(false)} className="px-4 py-2 bg-blue-600 text-white rounded-md">Save</button>
          </div>
        </SimpleModal>
      )}
      {studentFeedbackOpen && (
        <SimpleModal title="Submit Feedback" onClose={() => setStudentFeedbackOpen(false)}>
          <p className="text-sm text-slate-600 dark:text-slate-300 mb-3">Send feedback about your learning experience.</p>
          <textarea className="w-full h-28 border rounded-md px-3 py-2 dark:bg-slate-700 dark:text-white dark:border-slate-600" placeholder="Your feedback..." />
          <div className="mt-3 text-right">
            <button onClick={() => setStudentFeedbackOpen(false)} className="px-4 py-2 bg-blue-600 text-white rounded-md">Send</button>
          </div>
        </SimpleModal>
      )}
      {studentTestimonialsOpen && (
        <SimpleModal title="Testimonials" onClose={() => setStudentTestimonialsOpen(false)}>
          <p className="text-sm text-slate-600 dark:text-slate-300 mb-3">Write a short testimonial about PRISM.</p>
          <textarea className="w-full h-28 border rounded-md px-3 py-2 dark:bg-slate-700 dark:text-white dark:border-slate-600" placeholder="Your testimonial..." />
          <div className="mt-3 text-right">
            <button onClick={() => setStudentTestimonialsOpen(false)} className="px-4 py-2 bg-blue-600 text-white rounded-md">Submit</button>
          </div>
        </SimpleModal>
      )}
    </aside>
  );
};

export default RightSidebar;

function ActivityButton({ icon, label, primary, onClick }) {
  return (
    <button
      className={`w-full flex items-center gap-[clamp(0.5rem,1vw,0.75rem)] px-[clamp(0.75rem,1.5vw,1rem)] py-[clamp(0.5rem,1vh,0.75rem)] mb-[clamp(0.5rem,1vh,0.75rem)] rounded-xl text-[clamp(0.75rem,1vw,0.875rem)] font-medium shadow-sm transition-all duration-200 transform hover:scale-105 hover:shadow-md ${
        primary
          ? "bg-blue-600 hover:bg-blue-700 text-white dark:bg-blue-500 dark:hover:bg-blue-600"
          : "bg-white hover:bg-purple-100 text-gray-700 border border-gray-200 hover:border-purple-300 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-slate-200 dark:border-slate-700 dark:hover:border-slate-600"
      }`}
      onClick={onClick}
    >
      {icon}
      <span className="whitespace-nowrap">{label}</span>
    </button>
  );
}

function SimpleModal({ title, onClose, children }) {
  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 w-full max-w-lg mx-4 shadow-2xl relative">
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 text-2xl font-bold">×</button>
        <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-4">{title}</h3>
        {children}
      </div>
    </div>
  )
}