import React, { useEffect, useState } from 'react'
import LeftSidebar from '../components/Left'
import RightSidebar from '../components/Right'
import samsungLogo from '../assets/prism_logo.png'
import { MapPin } from 'lucide-react'
import { getCurrentUser } from '../services/auth'

const getInitials = (name) => {
  if (!name) return ''
  const parts = name.split(' ')
  if (parts.length === 1) return parts[0].charAt(0).toUpperCase()
  return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
}

const generateColorFromName = (name) => {
  const colors = ['#0077b6', '#0096c7', '#48cae4', '#90e0ef', '#ade8f4']
  let hash = 0
  for (let i = 0; i < (name || 'User').length; i++) {
    hash = (name.charCodeAt(i) + ((hash << 5) - hash)) >>> 0
  }
  return colors[Math.abs(hash % colors.length)]
}

export default function StudentDashboard() {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let mounted = true
    const load = async () => {
      try {
        const me = await getCurrentUser()
        if (!mounted) return
        setUser(me)
      } catch (_) {
        if (mounted) setUser({ name: 'Student', role: 'Student' })
      } finally {
        if (mounted) setLoading(false)
      }
    }
    load()
    return () => { mounted = false }
  }, [])

  const name = user?.name || user?.email?.split('@')[0] || 'Student'
  const role = user?.role || (localStorage.getItem('user_role') || 'Student')
  const college = user?.college || user?.student_profile?.college || ''
  const avatarUrl = user?.avatar_url || user?.student_profile?.avatar_url

  return (
    <div className="flex h-screen w-full bg-slate-100 text-slate-800 overflow-hidden dark:bg-slate-900 dark:text-slate-200">
      <LeftSidebar />

      <main className="flex-1 px-[2vw] py-[1.5vh] overflow-y-auto [&::-webkit-scrollbar]:w-2 [&::-webkit-scrollbar-track]:bg-slate-200 [&::-webkit-scrollbar-thumb]:bg-slate-400 dark:[&::-webkit-scrollbar-track]:bg-slate-800 dark:[&::-webkit-scrollbar-thumb]:bg-slate-600">
        <header className="flex justify-between items-center mb-[3vh]">
          <div>
            <h1 className="text-[clamp(1.75rem,3.5vw,2.25rem)] font-bold text-black dark:text-white">
              {loading ? 'Loading...' : `Welcome , ${name.split(' ')[0]}`}
            </h1>
            <p className="text-[clamp(0.875rem,1.2vw,1rem)] text-slate-500 dark:text-slate-400">Here’s your student space.</p>
          </div>
          <div className="flex items-center gap-[1vw]">
            <img src={samsungLogo} alt="PRISM" className="h-[clamp(2.5rem,4vw,3.5rem)] opacity-90" />
          </div>
        </header>

        {/* Profile Card - student focused (no worklet/mentees stats) */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-[1.5vw]">
          <div className="lg:col-span-3 relative overflow-hidden rounded-2xl border border-white/10 bg-white/60 backdrop-blur-xl shadow-lg p-[1.5vw] dark:bg-slate-900/50 dark:border-slate-700">
            <div className="pointer-events-none absolute -top-24 -right-24 w-80 h-80 rounded-full bg-gradient-to-br from-indigo-500/20 via-blue-500/15 to-cyan-400/20 blur-3xl"></div>
            <div className="pointer-events-none absolute -bottom-20 -left-20 w-72 h-72 rounded-full bg-gradient-to-tr from-blue-600/15 via-indigo-500/10 to-purple-500/15 blur-3xl"></div>

            <div className="flex items-start gap-[1.2vw] relative z-10">
              {avatarUrl ? (
                <img
                  src={avatarUrl}
                  alt="Avatar"
                  className="w-[clamp(4rem,6vw,5.5rem)] h-[clamp(4rem,6vw,5.5rem)] rounded-full object-cover shadow-md"
                />
              ) : (
                <div
                  className="w-[clamp(4rem,6vw,5.5rem)] h-[clamp(4rem,6vw,5.5rem)] rounded-full flex items-center justify-center text-white font-bold text-[clamp(1.5rem,2.5vw,2rem)] shadow-md flex-shrink-0"
                  style={{ backgroundColor: generateColorFromName(name) }}
                >
                  <span>{getInitials(name)}</span>
                </div>
              )}
              <div className="flex-1">
                <h2 className="text-[clamp(1.125rem,1.8vw,1.5rem)] font-bold text-slate-900 dark:text-white">{name}</h2>
                <div className="mt-[0.8vw] flex flex-wrap gap-[0.5vw]">
                  <span className="px-3 py-1.5 rounded-full text-[clamp(0.65rem,0.85vw,0.8rem)] bg-white/40 text-slate-800 border border-white/60 backdrop-blur dark:bg-white/10 dark:text-slate-200 dark:border-white/10">
                    {role}
                  </span>
                  {!!college && (
                    <span className="px-3 py-1.5 rounded-full text-[clamp(0.65rem,0.85vw,0.8rem)] bg-indigo-500/10 text-indigo-700 border border-indigo-500/20 backdrop-blur dark:text-indigo-200 flex items-center gap-1">
                      <MapPin className="w-4 h-4" /> {college}
                    </span>
                  )}
                  {user?.email && (
                    <span className="px-3 py-1.5 rounded-full text-[clamp(0.65rem,0.85vw,0.8rem)] bg-blue-500/10 text-blue-700 border border-blue-500/20 backdrop-blur dark:text-blue-200">
                      {user.email}
                    </span>
                  )}
                </div>
              </div>
            </div>

            <div className="mt-[1.5vw] text-sm text-slate-600 dark:text-slate-300">
              <p>Tip: Use the right sidebar to provide updates, share meeting updates, submit feedback, or add a testimonial.</p>
            </div>
          </div>
        </section>

        {/* Spacer for simplicity */}
        <div className="h-[2vh]"></div>
      </main>

      <RightSidebar />
    </div>
  )
}
