import React, { useState } from 'react'

export default function ShareArticle() {
  const [title, setTitle] = useState('')
  const [url, setUrl] = useState('')
  const [summary, setSummary] = useState('')
  const [submitted, setSubmitted] = useState(false)

  const handleSubmit = (e) => {
    e.preventDefault()
    // Placeholder: integrate with backend later
    setSubmitted(true)
    setTimeout(() => setSubmitted(false), 2500)
    setTitle(''); setUrl(''); setSummary('')
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 py-8">
      <div className="max-w-2xl mx-auto bg-white dark:bg-slate-800 rounded-2xl shadow p-6 border border-slate-200 dark:border-slate-700">
        <h1 className="text-xl font-bold mb-4 dark:text-white">Share Article / Blog</h1>
        <p className="text-sm text-slate-600 dark:text-slate-400 mb-6">Share a helpful article or your blog with your peers.</p>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-1 dark:text-slate-200">Title</label>
            <input value={title} onChange={(e)=>setTitle(e.target.value)} required className="w-full border rounded-lg px-3 py-2 dark:bg-slate-700 dark:text-white dark:border-slate-600" />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1 dark:text-slate-200">URL</label>
            <input type="url" value={url} onChange={(e)=>setUrl(e.target.value)} required placeholder="https://..." className="w-full border rounded-lg px-3 py-2 dark:bg-slate-700 dark:text-white dark:border-slate-600" />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1 dark:text-slate-200">Summary</label>
            <textarea rows={4} value={summary} onChange={(e)=>setSummary(e.target.value)} className="w-full border rounded-lg px-3 py-2 dark:bg-slate-700 dark:text-white dark:border-slate-600" />
          </div>
          <button type="submit" className="px-4 py-2 rounded-lg bg-blue-600 text-white hover:bg-blue-700">Share</button>
        </form>
        {submitted && (
          <div className="mt-4 text-green-600 dark:text-green-400">Thanks! Your article has been shared (demo).</div>
        )}
      </div>
    </div>
  )
}
